def interleave_strings(s1, s2):
    result = []
    i = 0
    n1, n2 = len(s1), len(s2)
    while i < n1 or i < n2:
        if i < n1:
            result.append(s1[i])
        if i < n2:
            result.append(s2[i])
        i += 1
    return ''.join(result)

def reverse_digits_in_string(s):
    digits = [c for c in s if '0' <= c <= '9']
    digits.reverse()
    result = []
    it = iter(digits)
    for c in s:
        if '0' <= c <= '9':
            result.append(next(it))
        else:
            result.append(c)
    return ''.join(result)

def matches_wildcard(s, pattern):
    m, n = len(s), len(pattern)
    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = True
    for j in range(1, n + 1):
        if pattern[j - 1] == '*':
            dp[0][j] = dp[0][j - 1]
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            pc = pattern[j - 1]
            if pc == '*':
                dp[i][j] = dp[i - 1][j] or dp[i][j - 1]
            elif pc == '?' or pc == s[i - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = False
    return dp[m][n]

def remove_repeated_words(s):
    words = s.split()
    result = []
    for w in words:
        if not result or result[-1] != w:
            result.append(w)
    return ' '.join(result)

def find_all_occurrences(s, sub):
    if sub == '':
        return []
    indices = []
    start = 0
    while True:
        idx = s.find(sub, start)
        if idx == -1:
            break
        indices.append(idx)
        start = idx + 1
    return indices

def is_isomorphic(s1, s2):
    if len(s1) != len(s2):
        return False
    map1 = {}
    map2 = {}
    for a, b in zip(s1, s2):
        if a in map1 and map1[a] != b:
            return False
        if b in map2 and map2[b] != a:
            return False
        map1[a] = b
        map2[b] = a
    return True

def count_case_transitions(s):
    count = 0
    for i in range(len(s) - 1):
        a, b = s[i], s[i + 1]
        if a.isalpha() and b.isalpha():
            if (a.isupper() and b.islower()) or (a.islower() and b.isupper()):
                count += 1
    return count

def leetspeak(s):
    mapping = {'a': '4', 'e': '3', 'i': '1', 'o': '0', 's': '5', 't': '7'}
    result = []
    for c in s:
        lower = c.lower()
        if lower in mapping:
            result.append(mapping[lower])
        else:
            result.append(c)
    return ''.join(result)

def reverse_words_with_even_length(s):
    words = s.split()
    result = []
    for w in words:
        if len(w) % 2 == 0:
            result.append(w[::-1])
        else:
            result.append(w)
    return ' '.join(result)

def count_palindrome_words(s):
    words = s.split()
    count = 0
    for w in words:
        lw = w.lower()
        if lw == lw[::-1]:
            count += 1
    return count

def find_anagram_matches(words, target):
    target_key = sorted(target.lower())
    return [w for w in words if sorted(w.lower()) == target_key]

def min_case_changes_alternating(s):
    letters = [c for c in s if c.isalpha()]
    if not letters:
        return 0
    cost_a = 0
    cost_b = 0
    for i, c in enumerate(letters):
        is_upper = c.isupper()
        if i % 2 == 0:
            if not is_upper:
                cost_a += 1
            if is_upper:
                cost_b += 1
        else:
            if is_upper:
                cost_a += 1
            if not is_upper:
                cost_b += 1
    return min(cost_a, cost_b)

def remove_kth_char(s, k):
    if k < 0 or k >= len(s):
        return s
    return s[:k] + s[k + 1:]

def middle_characters(s):
    n = len(s)
    if n == 0:
        return ''
    mid = n // 2
    if n % 2 == 1:
        return s[mid]
    else:
        return s[mid - 1:mid + 1]

def count_leading_zeros(s):
    count = 0
    for c in s:
        if c == '0':
            count += 1
        else:
            break
    return count

def count_word_length_frequency(s):
    words = s.split()
    freq = {}
    for w in words:
        freq[len(w)] = freq.get(len(w), 0) + 1
    return freq

def has_repeated_substring_pattern(s):
    n = len(s)
    if n == 0:
        return False
    for length in range(1, n // 2 + 1):
        if n % length == 0:
            candidate = s[:length]
            if candidate * (n // length) == s:
                return True
    return False
